"""Generate a self-contained report only after exact-ROM release gates pass."""
from pathlib import Path
import base64,html,json
from verify_release import verify
R=Path(__file__).resolve().parents[1];d=verify()
esc=lambda s:html.escape(str(s))
def picture(p):return 'data:image/png;base64,'+base64.b64encode((R/p).read_bytes()).decode()
rows=[];measurements=[]
for case in d['driving']['cases']:
    w=json.loads((R/case['report']).read_text())
    if case['name'].startswith('negative-'):continue
    marks={c['name']:c for c in w['checks']};m=marks['03-accelerator-moves-car']['details'];item={'case':case['name'],**m};measurements.append(item)
    rows.append('<tr><td>'+esc(case['name'])+'</td><td>'+f"{m['distance_m']:.1f} m"+'</td><td>'+f"{m['completed_game_fps']:.1f}"+'</td><td>'+f"{m['game_clock_ratio']:.3f}"+'</td><td class="pass">PASS</td></tr>')
summary={'status':'Experimental drivable racing verified in bounded stock-emulator scenarios; full TriggerRally conversion remains INCOMPLETE','native_rom_compiled':True,'rom_bytes':d['info']['rom_bytes'],'rom_sha256':d['rom_sha256'],'core_sha256':d['core_sha256'],'native_execution':'68000 bootstrap host; DSP game/50-Hz physics/audio; 42Bastian GPU engine','drivable_racing_verified':True,'playability_scope':'Controlled throttle/brake/steering/clock/frame-rate checks for all shipped NTSC course/car selections and both Base cars in PAL; actual desktop keyboard/pixels and genuine Base/car0 finishes. Not all routes, worst-case FPS or hardware.','full_feature_parity':False,'requested_full_conversion_delivered':False,'physics_hz':50,'normal_boot_configurations':13,'specific_black_screen_controls':5,'normal_driving_configurations':8,'specific_movement_timing_controls':2,'full_desktop_interaction_checks':len(d['desktop']['checks']),'both_full_core_bios_paths':True,'full_core_interaction_checks':sum(len(r['checks']) for r in d['full_core'].values()),'driving_measurements':measurements,'dsp_arithmetic_operations':d['dsp_math']['arithmetic_operations'],'render_matrix_cases':d['dsp_math']['render_matrix_cases'],'legacy_68000_arithmetic_operations':d['math']['operations'],'two_clean_source_builds_match_tested_rom':True,'content_rights':'Original content remains separately restricted; obtain permission before redistribution. Build-tool terms are separate.','missing':['native track editor','persistent tracks/runs/settings/best times','profiles/favorites/sharing/network bridge','complete source replay/ghost/effects/audio parity','complete terrain/scenery/material/hierarchy fidelity','worst-case performance and physical-hardware validation'],'limitations':['Finite tests cannot prove never freezing.','This is not a 60-FPS game; dense scenery/contact/recovery can be slower than controlled driving.','Historical 0.7 mixed-state FPS and new controlled driving FPS are different scenarios, not a like-for-like benchmark ratio.'],'evidence':d['evidence']}
(R/'releases/port-summary.json').write_text(json.dumps(summary,indent=2)+'\n')
after=picture('artifacts/playability-regression/ntsc-track-0-car-0/03-accelerator-moves-car.png');finish=picture('artifacts/playability-regression/ntsc-track-2-car-0/07-course-finished-by-driving.png')
case_rows=''.join('<tr><td>'+esc(c['name'])+'</td><td class="pass">PASS</td><td>'+esc(c['expected_failure'] or 'Actual cartridge boot / scene / input / reset')+'</td></tr>' for c in d['suite']['cases'])
css='''*{box-sizing:border-box}body{margin:0;background:#10141a;color:#eef1f5;font:16px/1.65 system-ui,sans-serif}main{max-width:1080px;margin:auto;padding:36px 24px 60px}header{color:#adb9c8;font-size:12px;letter-spacing:1.5px;border-bottom:1px solid #354151;padding-bottom:18px}h1{font-size:clamp(34px,6vw,60px);line-height:1.1;margin:24px 0}h1 span{color:#eea95e}h2{line-height:1.3}.lead{color:#b9c5d4;font-size:19px}.notice{padding:18px 22px;border:1px solid #815d33;background:#2a2118;border-left:4px solid #eea95e;margin:24px 0}.stats,.figures{display:grid;grid-template-columns:repeat(2,1fr);gap:18px;margin:24px 0}.stat{padding:20px;border:1px solid #354151;background:#1a222d;border-radius:10px}.stat b{font-size:32px;color:#9de3b5;display:block}.stat small{color:#b9c5d4}figure{margin:0;background:#000;border:1px solid #354151;border-radius:10px;overflow:hidden}figure img{width:100%;height:285px;object-fit:contain;image-rendering:pixelated}figcaption{background:#1a222d;padding:15px;font-size:13px;color:#b9c5d4}.table{overflow-x:auto;border:1px solid #354151;border-radius:9px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;padding:11px 14px;border-bottom:1px solid #354151}th{background:#1a222d;color:#b9c5d4}.pass{color:#9de3b5;font-weight:700}code,pre{font:13px/1.7 ui-monospace,monospace}pre{padding:18px;border:1px solid #354151;background:#080b10;white-space:pre-wrap;overflow-wrap:anywhere;border-radius:9px}section{margin-top:35px}li{margin:8px 0;color:#b9c5d4}footer{border-top:1px solid #354151;margin-top:32px;padding-top:20px;color:#adb9c8;font-size:12px}@media(max-width:650px){.stats,.figures{grid-template-columns:1fr}figure img{height:auto}main{padding:24px 16px}}'''
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Trigger Rally Jaguar — driving correction</title><style>{css}</style></head><body><main>
<header>TRIGGER RALLY / ATARI JAGUAR · ACTUAL EMULATOR EVIDENCE · 2026-10-16</header>
<h1>The accelerator now<br><span>moves the car.</span></h1>
<p class="lead">A native DSP game/physics implementation, local binary32 arithmetic and concurrent GPU rendering replace the earlier multi-second game frames. The original 68000 cartridge boot paths and the requested 42Bastian renderer remain real native code.</p>
<div class="notice"><strong>DRIVABLE RACING, NOT FULL FEATURE PARITY.</strong> This is an experimental low-frame-rate classic-console port, not a 60-FPS release or a completed conversion of the editor, persistence, profiles/network/sharing, replay/ghost and fidelity requirements. Dense contacts/scenery/recovery may be slower. Physical hardware is untested.</div>
<div class="stats"><div class="stat"><b>8 / 8</b><small>stock-clock driving configurations</small></div><div class="stat"><b>2 / 2</b><small>specific no-power / slow-racing controls rejected</small></div><div class="stat"><b>13 + 5</b><small>healthy boot configurations + intended black/frozen controls</small></div><div class="stat"><b>{len(d['desktop']['checks'])} + {sum(len(r['checks']) for r in d['full_core'].values())}</b><small>actual desktop + both full core BIOS-path checks</small></div></div>
<div class="figures"><figure><img src="{after}" alt="Unretouched live Virtual Jaguar cartridge capture while accelerating"><figcaption>Actual stock-core cartridge output under real throttle input. Native position/speed, changing 3D pixels and completed game frames are checked together; an emulator FPS status is not used as game FPS.</figcaption></figure><figure><img src="{finish}" alt="Actual Base course finish reached through ordered checkpoints by driving"><figcaption>Actual Base/car0 FINISH after both ordered checkpoints. The test uses controller input only and never invokes replay to manufacture a course-completion result.</figcaption></figure></div>
<section><h2>Timed accelerator checks</h2><p>Each controlled window holds A for 2.5 emulated seconds after the native countdown. Required: physical displacement/speed, 0.90–1.10 race-clock ratio, 12 NTSC / 10 PAL completed FPS, changing live 3D pixels, braking, heading change and pause.</p><div class="table"><table><thead><tr><th>Scenario</th><th>Distance / 2.5 s</th><th>Game FPS</th><th>Clock ratio</th><th>Result</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div></section>
<section><h2>Native changes</h2><ul><li>68000 host copies/starts the real DSP image; no host-side game simulation or emulator overclock.</li><li>Jerry runs the state machine, controller scans, 50-Hz force/suspension/contact simulation and opposite-bank PCM interrupt mixer.</li><li>Tom renders complete immutable scene submissions using the adapted <strong>42Bastian jag_3d_engine</strong>; DSP simulation overlaps GPU rasterization.</li><li>Static world transforms/spheres are cached. Render-only wheel matrices use the engine's Q15 precision in the original composition order.</li><li>Both signed BIOS and native copy entries remain. A real compatibility jump at cartridge $802000 prevents a frontend heuristic from silently forcing the boot ROM on.</li><li>10,240 actual-DSP arithmetic cases, edge classifications, fixed-point matrix checks, legacy 68000 arithmetic and two clean source builds are independently required.</li></ul></section>
<section><h2>Boot and watchdog matrix</h2><div class="table"><table><thead><tr><th>Case</th><th>Result</th><th>Required behavior / intended rejection</th></tr></thead><tbody>{case_rows}</tbody></table></div></section>
<section><h2>Controls and reproduction</h2><p><strong>Virtual Jaguar 2.1.3: L is Jaguar A/start/throttle. J is Jaguar C/handbrake.</strong> Z/C steer, K brakes, P pauses, O returns to menu. Number keys provide recovery/restart/camera functions. Follow the track instead of holding throttle into scenery.</p><pre>make -j4 all
make test-core
make test-driving
make test
python3 tools/check_reproducibility.py
make release</pre><pre>Game ROM SHA-256\n{d['rom_sha256']}\n\nTested core SHA-256\n{d['core_sha256']}</pre></section>
<section><h2>Remaining scope and finite coverage</h2><p>The original full-port requirements remain active; no scope reduction is assumed. Native editor, persistent data, profile/sharing/network, complete replay/effects/audio and several terrain/scenery/material/hierarchy details are still incomplete. These bounded tests do not certify all driving paths, durations, emulator versions or physical hardware, and cannot prove that a game will never freeze.</p><p>Original game content is separately restricted. Obtain permission before publication/redistribution. Tool licenses are separate; see LICENSES.md and the unchanged source archives.</p><details><summary>Hash-bound evidence files</summary><pre>{esc(chr(10).join(d['evidence']))}</pre></details></section><footer>All pictured output is captured from the actual cartridge in Virtual Jaguar. No generated imagery, fixture substitution or target-state injection. Report is self-contained and works offline.</footer></main></body></html>'''
(R/'releases/port-report.html').write_text(page)
